if(!defined('LOYF_RUNTIME_DISPOSABLE')){define('LOYF_RUNTIME_DISPOSABLE',true);}require __DIR__.'/assertions.php';
$owner=getenv('LOYF13_OWNER');$active=get_option('active_plugins');loyf_assert(in_array($owner.'/'.$owner.'.php',$active,true),'Native expected edition active');$other='wc-loyalty'===$owner?'loyalty-for-woocommerce':'wc-loyalty';loyf_assert(!in_array($other.'/'.$other.'.php',$active,true),'Native activation prevents simultaneous active flags');loyf_assert(class_exists('YOWCL_Points_Transaction',false),'Native canonical owner loaded');$file=(new ReflectionClass('YOWCL_Points_Transaction'))->getFileName();loyf_assert(false!==strpos($file,'/wp-content/plugins/'.$owner.'/'),'Exactly one native canonical class owner');
if('wc-loyalty'===$owner){loyf_assert(class_exists('YOWCL_Loyalty',false),'Premium active owner');if(class_exists('YOWCL_Free_Core',false)){loyf_assert(!YOWCL_Free_Core::owns(),'Simultaneous activation excludes Free mutation ownership');}}else{loyf_assert(!class_exists('YOWCL_Loyalty',false)&&YOWCL_Free_Core::owns(),'Free owner after Premium deactivation');}
echo "Native activation ordering/cold reload owner PASS $owner; simulated entitlement.\n";
